"""Build test files in memory. Every fixture is synthetic and generated by code (no hand-edited binaries)."""

from __future__ import annotations

import csv
import datetime as dt
import io
import zipfile

import openpyxl
import xlwt
from msoffcrypto.format.ooxml import OOXMLFile


def xlsx_multi_sheet() -> bytes:
    """Visible 'Sales' (with a formula lacking a cached value), hidden, very hidden, empty sheets, a chart sheet."""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Sales"
    ws.append(["Monthly sales report"])  # title row: header is on row 2
    ws.append(["Date", "City", "Amount (PKR)", "Doubled"])
    ws.append([dt.date(2026, 4, 3), "Lahore", 1250.5, "=C3*2"])
    ws.append(["03/04/2026", " lahore", "Rs 1,000", "=C4*2"])
    ws.append([dt.date(2026, 4, 5), "Karachi", 900, None])
    hidden = wb.create_sheet("Lookup")
    hidden.sheet_state = "hidden"
    hidden.append(["Code", "Name"])
    hidden.append([1, "North"])
    very = wb.create_sheet("Internal")
    very.sheet_state = "veryHidden"
    very.append(["secret"])
    wb.create_sheet("Empty")
    wb.create_chartsheet("Chart")
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def xlsx_simple(rows: int = 3, cols: int = 3) -> bytes:
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Data"
    ws.append([f"col{c}" for c in range(cols)])
    for r in range(rows):
        ws.append([r * cols + c for c in range(cols)])
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def with_macros(xlsx: bytes) -> bytes:
    """Add a VBA project part (inert bytes) to an xlsx container, as an .xlsm file would have."""
    src = zipfile.ZipFile(io.BytesIO(xlsx))
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            dst.writestr(item, src.read(item.filename))
        dst.writestr("xl/vbaProject.bin", b"\x00inert-test-bytes\x00")
    return out.getvalue()


def zip_bomb_like(uncompressed_mb: int) -> bytes:
    """A valid-looking workbook with one large, highly compressible part."""
    src = zipfile.ZipFile(io.BytesIO(xlsx_simple()))
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            dst.writestr(item, src.read(item.filename))
        dst.writestr("xl/media/padding.bin", b"\x00" * (uncompressed_mb * 1024 * 1024))
    return out.getvalue()


def docx_like() -> bytes:
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w") as z:
        z.writestr("word/document.xml", "<w:document/>")
    return out.getvalue()


def encrypted_xlsx() -> bytes:
    plain = io.BytesIO(xlsx_simple())
    out = io.BytesIO()
    OOXMLFile(plain).encrypt("test-password", out)
    return out.getvalue()


def xls_legacy() -> bytes:
    wb = xlwt.Workbook()
    ws = wb.add_sheet("Claims")
    for c, h in enumerate(["Claim ID", "Amount", "Status"]):
        ws.write(0, c, h)
    ws.write(1, 0, "C-001")
    ws.write(1, 1, 15000.5)
    ws.write(1, 2, "Approved")
    ws.write(2, 0, "C-002")
    ws.write(2, 1, 4200)
    ws.write(2, 2, "Pending")
    hidden = wb.add_sheet("Codes")
    hidden.write(0, 0, "x")
    hidden.visibility = 1
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


CSV_ROWS = [["Name", "City", "Amount"], ["Ayesha", "Lahore", "1,250"], ["Bilal", "Karachi", "900"]]


def csv_bytes(encoding: str = "utf-8", delimiter: str = ",", rows: list[list[str]] | None = None) -> bytes:
    buf = io.StringIO()
    csv.writer(buf, delimiter=delimiter, lineterminator="\r\n").writerows(rows or CSV_ROWS)
    return buf.getvalue().encode(encoding)
